key=lambda x,y: ('m%d'%-x if x<0 else '%d'%x)+'_'+('m%d'%-y if y<0 else '%d'%y)
def xf4_cands(p,xf):   # كما في make بالكود: الصورة، ثم المحور الآخر، ثم عكس الإشارتين، ثم الدوران الآخر
    x,y=p; img={'refV':(-x,y),'refH':(x,-y),'rot90':(-y,x)}[xf]; alt={'refV':[(x,-y),(-x,-y)],'refH':[(-x,y),(-x,-y)],'rot90':[(y,-x),(-x,-y),(-x,y)]}[xf]
    out=[]
    for c in [img,*alt,(-y,x)]:
        if c not in out and c!=tuple(p): out.append(c)
    return out[:3]
